    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    nonbg = [v for v in set(v for row in grid for v in row) if v != bg]
    if len(nonbg) == 1:
        band = nonbg[0]
        for r, row in enumerate(grid):
            if all(v == band for v in row):
                continue
            # Find a leading band run followed by background; mark the first bg cell.
            n = 0
            while n < w and row[n] == band:
                n += 1
            if n and n < w and all(v == bg for v in row[n:]) and n >= w // 2:
                out[r][n] = 1
        return out
    # In the patterned case, identify the repeated 4x14 signature and color
